// Relay test fixtures + persona helpers (NOT a test file — the name has no
// `.test.` segment, so `node --test` ignores it). Written straight from the
// contract; mirrors the seed pattern in packages/db/seeds/0002_core_seed.sql:
// provision synthetic users + admission tokens AS SUPERUSER, then drive the
// AUDITED writers under a per-persona jwt claim. We NEVER raw-insert a books or
// event row (CLAUDE.md law) — events are generated by calling the writers, which
// append their domain events in-txn (§0.3 uniform emission law).
//
// Connection: env ONLY (lib/relay.mjs connConfig). Local target is the throwaway
//   PGHOST=127.0.0.1 PGPORT=5544 PGUSER=postgres PGDATABASE=clara_rt_test (trust).

import { createHash, randomUUID } from "node:crypto";
import { makePool } from "../lib/relay.mjs";

// ---------------------------------------------------------------------------
// Pool + persona impersonation (a fresh checkout per call; RESET ALL on release
// so no session state — role / jwt claims — leaks to the next checkout).
// ---------------------------------------------------------------------------

let _pool = null;
export function getPool() {
  if (!_pool) _pool = makePool({ max: 8 });
  return _pool;
}
export async function endPool() {
  if (_pool) {
    await _pool.end();
    _pool = null;
  }
}

function assertRole(role) {
  if (!/^clara_[a-z_]+$/.test(role)) throw new Error(`refusing SET ROLE to non-clara identifier: ${role}`);
  return role;
}

/**
 * Run fn(client) under an impersonated identity. role null ⇒ the superuser login
 * (RESET ROLE). jwtSub set ⇒ session-level request.jwt.claims (human autocommit).
 */
export async function withActor({ role = null, jwtSub = null }, fn) {
  const client = await getPool().connect();
  try {
    if (role) await client.query(`set role ${assertRole(role)}`);
    else await client.query("reset role");
    if (jwtSub !== null) {
      await client.query("select set_config('request.jwt.claims', $1, false)", [
        JSON.stringify({ sub: jwtSub, role: "authenticated" }),
      ]);
    }
    return await fn(client);
  } finally {
    try {
      await client.query("rollback");
    } catch {
      /* no open txn */
    }
    try {
      await client.query("reset role");
    } catch {
      /* best-effort */
    }
    try {
      await client.query("reset all");
    } catch {
      /* best-effort */
    }
    client.release();
  }
}

export const asRoot = (fn) => withActor({}, fn);
export const asHuman = (sub, fn) => withActor({ role: "clara_authenticated", jwtSub: sub }, fn);
export const asRuntime = (fn) => withActor({ role: "clara_runtime" }, fn);
export const asFnOwner = (fn) => withActor({ role: "clara_fn_owner" }, fn);

export const rootQuery = (sql, params) => asRoot((c) => c.query(sql, params));
export const humanQuery = (sub, sql, params) => asHuman(sub, (c) => c.query(sql, params));

// ---------------------------------------------------------------------------
// Small utilities
// ---------------------------------------------------------------------------

let _n = 0;
export const opk = (tag = "op") => `${tag}_${Date.now().toString(36)}_${(_n++).toString(36)}_${randomUUID().slice(0, 8)}`;
export const sha = (seed) => createHash("sha256").update(String(seed)).digest("hex");

/**
 * Probe whether the Slice-3 (0005) surface is present — the rig's ensureReady
 * pattern (§4). Tests SKIP cleanly when absent instead of crashing. We check the
 * emission helper AND a couple of relay tables so a partial apply also skips.
 */
export async function probeReady() {
  const r = await rootQuery(
    `select
       (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
         where n.nspname = 'clara' and p.proname = '_append_event') as fn,
       (select count(*) from pg_tables where schemaname = 'clara'
         and tablename in ('domain_events','wake_intents','relay_checkpoints','relay_dead_letters',
                           'taxonomy_active','trigger_taxonomy','firm_event_seq')) as tbls`,
  );
  return Number(r.rows[0].fn) === 1 && Number(r.rows[0].tbls) === 7;
}

// ---------------------------------------------------------------------------
// Writer wrappers (named args — the contract's documented parameter names).
// ---------------------------------------------------------------------------

export async function createFirm(sub, { name, token, opKey }) {
  const r = await humanQuery(
    sub,
    "select clara.create_firm(p_name => $1, p_admission_token => $2, p_op_key => $3) as receipt",
    [name, token, opKey],
  );
  return r.rows[0].receipt.firm_id;
}

export async function createClient(sub, { name, opKey }) {
  const r = await humanQuery(sub, "select clara.create_client(p_name => $1, p_op_key => $2) as receipt", [name, opKey]);
  const id = r.rows[0].receipt.client_id;
  await activateOnboardingClient(sub, id);
  return id;
}

// Membership verbs (human lane, granted to clara_authenticated) — added ONLY for the
// [R4-F1] Gate-O bridge below. add_member returns { membership_id }; we read it off
// the receipt so the temp-admin ceremony needs no separate lookup query.
export async function addMember(sub, { firm, user, role: memberRole, opKey }) {
  const r = await humanQuery(
    sub,
    "select clara.add_member(p_firm => $1, p_user => $2, p_role => $3, p_op_key => $4) as receipt",
    [firm, user, memberRole, opKey],
  );
  return r.rows[0].receipt.membership_id;
}

export async function removeMember(sub, { membership, opKey }) {
  await humanQuery(sub, "select clara.remove_member(p_membership => $1, p_op_key => $2)", [membership, opKey]);
}

/**
 * [R4-F1] (ratchet round-4 finding) Drive a freshly-created fixture client from
 * ONBOARDING to ACTIVE through the audited Gate-O ceremony — without relaxing any
 * product law. Ported from packages/db/tests/rig-fixtures.mjs (createClient /
 * bridge-v2), adapted to the relay tests' actor/JWT plumbing.
 *
 * Migration 0017's creator law makes clara.create_client birth an ONBOARDING client
 * with an open plan (no Gate-O bypass). An onboarding client makes
 * enqueue_invoice_facts return `skipped_client_onboarding` instead of `queued`
 * (the finding's classify-consumer failure). Lawful activation:
 *   1. Add a deferred `carry_down_deferred` item via update_onboarding_plan — the
 *      runtime-interview CAS writer (EXECUTE → clara_runtime); its p_answered_by must
 *      be an active bookkeeper+ (the firm owner qualifies). This item satisfies the
 *      commit's opening-position gate.
 *   2. commit_client_onboarding by an admin DISTINCT from every plan contributor
 *      (Gate O). buildFirm has a single owner who is the sole contributor, so we mint
 *      a TEMPORARY admin (add_member → commit → remove_member) — the distinct-checker
 *      route, no attestation needed. If the firm already has another non-contributor
 *      admin/owner, that one commits and no temp is minted.
 * Pre-0017 (client born 'active') the status check no-ops, so callers stay bimodal-green.
 */
async function activateOnboardingClient(sub, client) {
  const cl = (await rootQuery("select status, firm_id from clara.clients where id = $1", [client])).rows[0];
  if (cl?.status !== "onboarding") return;
  const plan = (
    await rootQuery(
      "select id, revision_token from clara.onboarding_plans where client_id = $1 and state = 'open' order by created_at desc limit 1",
      [client],
    )
  ).rows[0];
  if (!plan) throw new Error("[R4-F1] Gate-O bridge: onboarding client without an open plan");
  await asRuntime((c) =>
    c.query(
      "select clara.update_onboarding_plan(p_plan => $1, p_expected_revision => $2, p_items => $3::jsonb, p_answered_by => $4, p_op_key => $5)",
      [
        plan.id,
        plan.revision_token,
        JSON.stringify([{ item_kind: "todo", item_key: "carry_down_deferred", state: "deferred" }]),
        sub,
        opk("bridge"),
      ],
    ),
  );
  const rev = (await rootQuery("select revision_token from clara.onboarding_plans where id = $1", [plan.id])).rows[0]
    .revision_token;
  const commitAs = (who) =>
    humanQuery(
      who,
      "select clara.commit_client_onboarding(p_client => $1, p_plan => $2, p_expected_plan_revision => $3, p_op_key => $4)",
      [client, plan.id, rev, opk("bridgec")],
    );
  // Prefer an existing non-contributor admin/owner; otherwise mint a temporary admin.
  const alt = (
    await rootQuery(
      `select user_id from clara.firm_memberships
        where firm_id = $1 and status = 'active' and role in ('admin','owner') and user_id <> $2
        order by case role when 'owner' then 0 else 1 end, created_at limit 1`,
      [cl.firm_id, sub],
    )
  ).rows[0]?.user_id;
  if (alt) {
    await commitAs(alt);
  } else {
    const temp = await insertUser("bridge", `tmp_${client.slice(0, 8)}`);
    const membership = await addMember(sub, { firm: cl.firm_id, user: temp, role: "admin", opKey: opk("bta") });
    await commitAs(temp);
    await removeMember(sub, { membership, opKey: opk("btr") });
  }
}

// ---------------------------------------------------------------------------
// [Wave-F Track A, F-A7 gamma, CI #331 fold] the classify-lane typed-consent gate
// (0123's own AT-ENQUEUE gate on _enqueue_invoice_facts_core): a NULL-kind document
// filed to a client now needs that client's live 'document_processing' typed egress
// consent+activation, or the classify task the enqueue mints comes back TERMINAL
// 'failed' instead of 'queued'. Ported from packages/db/tests/rig-docs-fixtures.mjs's
// ensureClassifyConsent — SAME shape: granted through the REAL governed verbs
// (classify_consent_evidence_document -> grant_client_egress_purpose ->
// activate_client_egress_purpose, never a raw table write), frontier-gated (a true
// no-op below 0123 via a live catalog check, never a version-number string), and
// scoped to fire ONLY where the wall actually binds — the caller decides that by
// calling this ONLY when it is about to file/enqueue a NULL-kind document (this file
// does not call it unconditionally from buildFirm/createClient, so a runtime test
// exercising an unconsented firm on purpose is unaffected). `owner` is the caller's
// own resolved firm owner (every call site in this package already passes one — no
// internal firm-membership resolution is needed here, unlike the DB package's
// version, which has to handle a non-owner `sub`).
// ---------------------------------------------------------------------------

let _classifyGammaReady = null;
async function classifyGammaReady() {
  if (_classifyGammaReady !== null) return _classifyGammaReady;
  const r = await rootQuery(
    `select
       (select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
          where n.nspname='clara' and p.proname='classify_consent_evidence_document') as fn,
       (select pg_get_constraintdef(con.oid)
          from pg_constraint con join pg_class c on c.oid=con.conrelid join pg_namespace n on n.oid=c.relnamespace
         where n.nspname='clara' and c.relname='client_egress_purpose_consents' and con.contype='c'
           and con.conname='ck_client_egress_purpose_consents_purpose_f_a1') as purpose_check`,
  );
  const row = r.rows[0];
  _classifyGammaReady = Boolean(row.fn && row.purpose_check && /document_processing/.test(row.purpose_check));
  return _classifyGammaReady;
}

/** Grant + activate 'document_processing' for (firm, client) through the real governed
 *  verbs, as `owner`. Idempotent (a second call for the same firm+client is a no-op)
 *  and a silent no-op below the gamma frontier. */
export async function ensureClassifyConsent(owner, { firm, client }) {
  if (!(await classifyGammaReady())) return;
  const live = await rootQuery(
    `select 1 from clara.client_egress_purpose_activations a
       join clara.client_egress_purpose_consents c
         on c.id=a.consent_id and c.firm_id=a.firm_id and c.client_id=a.client_id and c.purpose=a.purpose
      where a.firm_id=$1 and a.client_id=$2 and a.purpose='document_processing'
        and a.deactivated_at is null and c.revoked_at is null`,
    [firm, client],
  );
  if (live.rowCount > 0) return;
  // Mint the consent-evidence document via a direct named call to _seed_verified_document
  // (superuser lane — granted to no app role, matching packages/db's own rig path): the
  // matcher-testkit's seedVerifiedDocument wrapper has no document_kind parameter.
  const evSha = sha(`consent_ev_${opk("ce")}`);
  const evidence = (
    await rootQuery(
      `select clara._seed_verified_document(p_firm=>$1,p_client=>null,p_sha256=>$2,p_filename=>'consent.pdf',
         p_mime=>'application/pdf',p_bytes=>2048,p_storage_path=>$3,p_uploaded_by=>$4,p_page_count=>1,
         p_document_kind=>'consent_evidence',p_financial_date=>null,p_resolution=>null) as r`,
      [firm, evSha, `firms/${firm}/docs/${evSha}.pdf`, owner],
    )
  ).rows[0].r.document_id;
  await rootQuery("update clara.documents set bytes_verified_at=coalesce(bytes_verified_at,now()) where id=$1", [evidence]);
  await humanQuery(
    owner,
    "select clara.classify_consent_evidence_document(p_document=>$1,p_reason=>$2,p_op_key=>$3)",
    [evidence, "rig fixture consent letter (F-A7 gamma runtime convenience)", opk("cce")],
  );
  const grant = await humanQuery(
    owner,
    `select clara.grant_client_egress_purpose(p_client=>$1,p_purpose=>'document_processing',
       p_evidence_document=>$2,p_scope_note=>$3,p_op_key=>$4) as r`,
    [client, evidence, "rig fixture classify consent", opk("gdp")],
  );
  const consentId = grant.rows[0].r.consent_id;
  await humanQuery(
    owner,
    `select clara.activate_client_egress_purpose(p_client=>$1,p_purpose=>'document_processing',
       p_consent=>$2,p_op_key=>$3)`,
    [client, consentId, opk("adp")],
  );
}

// ---------------------------------------------------------------------------
// Synthetic wake-bound event source (post-0007). Migration 0007 retired both SQL
// ingest writers — clara.ingest_document / clara.wake_ingest_document now RAISE
// (CLR13) with EXECUTE revoked — and taxonomy v2 routes document.ingested to
// 'ignore', so document.ingested can no longer stand in as the relay's wake-bound
// event. These relay tests prove the RELAY mechanics (routing, drain, checkpoint,
// dead-letter, exactly-once, fairness, HALT), NOT document semantics — so we drive
// them with a rig-only synthetic wake-bound event type registered into the ACTIVE
// taxonomy as 'background_review' (the same decision document.ingested carried
// under v1). Events are appended through the audited clara._append_event helper as
// clara_fn_owner (its EXECUTE grant) — never a raw domain_events insert — exactly
// as the taxonomy suite already emits its synthetic uncovered types.
// ---------------------------------------------------------------------------

/** The rig-only wake-bound event type these tests emit in place of the retired
 *  document.ingested wake path. A STABLE name so registration is idempotent. */
export const WAKE_EVENT_TYPE = "rig.relay.wake";

const _APPEND_WAKE_SQL = `select clara._append_event(
    p_firm => $1, p_type => $2, p_client => null, p_actor => $3,
    p_obo => null, p_wake_kind => null, p_entry => null, p_document => null,
    p_resolution => null, p_payload => $4::jsonb) as seq`;

/** Idempotently register WAKE_EVENT_TYPE and map it to 'background_review' in the
 *  CURRENTLY-ACTIVE taxonomy version. Purely ADDITIVE — it never changes an
 *  existing type's decision, so it is invisible to every other suite. Re-run on
 *  every pump so a mid-suite taxonomy repoint (the flip test copies the active
 *  rows forward) stays covered. */
export async function ensureWakeType() {
  await rootQuery(
    `insert into clara.event_types (name, client_scoped, description)
       values ($1, false, 'rig synthetic wake-bound source (post-0007 relay tests)')
     on conflict (name) do nothing`,
    [WAKE_EVENT_TYPE],
  );
  await rootQuery(
    `insert into clara.trigger_taxonomy (version, event_type, decision)
       select a.version, $1, 'background_review' from clara.taxonomy_active a
     on conflict (version, event_type) do nothing`,
    [WAKE_EVENT_TYPE],
  );
}

/** The firm that owns a client (superuser read — bypasses RLS). */
export async function firmOfClient(client) {
  const r = await rootQuery("select firm_id from clara.clients where id = $1", [client]);
  return r.rows[0]?.firm_id ?? null;
}

/**
 * Emit ONE synthetic wake-bound event for a firm via clara._append_event (as
 * clara_fn_owner, autocommit) and return the resulting row
 * { id, firm_id, seq, event_type }. Replaces the retired ingest_document wake path.
 */
export async function emitWakeEvent(firm, { actor = null, payload = {} } = {}) {
  await ensureWakeType();
  return asFnOwner(async (c) => {
    const s = await c.query(_APPEND_WAKE_SQL, [firm, WAKE_EVENT_TYPE, actor, JSON.stringify(payload)]);
    const seq = Number(s.rows[0].seq);
    const e = await c.query(
      "select id, firm_id, seq, event_type from clara.domain_events where firm_id = $1 and seq = $2",
      [firm, seq],
    );
    return e.rows[0];
  });
}

// ---------------------------------------------------------------------------
// Fixtures — a fresh firm + owner + one client per call (unique names, so
// parallel/re-run never collide). Superuser provisions users + admission tokens.
// ---------------------------------------------------------------------------

export async function insertUser(prefix, tag) {
  const id = randomUUID();
  await rootQuery("insert into clara.users (id, display_name, email, is_agent) values ($1, $2, $3, false)", [
    id,
    `${prefix}_${tag}`,
    `${prefix}_${tag}@relay.test`,
  ]);
  return id;
}

export async function seedAdmission(note = "relay rig admission") {
  const token = randomUUID();
  await rootQuery("insert into clara.firm_admissions (token, note) values ($1, $2)", [token, note]);
  return token;
}

/** Build one firm with an owner and one client. Returns { prefix, owner, firm, client }. */
export async function buildFirm(label = "f") {
  const prefix = `rly_${Date.now().toString(36)}_${randomUUID().slice(0, 6)}_${label}`;
  const owner = await insertUser(prefix, "owner");
  const token = await seedAdmission();
  const firm = await createFirm(owner, { name: `${prefix}_firm`, token, opKey: opk("firm") });
  const client = await createClient(owner, { name: `${prefix}_client`, opKey: opk("cli") });
  return { prefix, owner, firm, client };
}

/**
 * Drive N wake-bound events for a client's firm → N wake_intents on drain. Emits
 * synthetic WAKE_EVENT_TYPE events through the audited clara._append_event helper
 * (post-0007 the document.ingested wake path is retired — see emitWakeEvent). Every
 * call appends fresh events (_append_event has no op_key dedup). `tag` is carried
 * into each event payload for call-site traceability. Returns the emitted seqs.
 */
export async function pumpDocuments(ownerSub, client, n, tag = "doc") {
  const firm = await firmOfClient(client);
  await ensureWakeType();
  return asFnOwner(async (c) => {
    const seqs = [];
    for (let i = 0; i < n; i++) {
      const s = await c.query(_APPEND_WAKE_SQL, [firm, WAKE_EVENT_TYPE, ownerSub, JSON.stringify({ tag, i })]);
      seqs.push(Number(s.rows[0].seq));
    }
    return seqs;
  });
}

// ---------------------------------------------------------------------------
// State readers (superuser — bypass RLS so assertions see all firms).
// ---------------------------------------------------------------------------

export async function headSeq(firmId) {
  const r = await rootQuery("select n from clara.firm_event_seq where firm_id = $1", [firmId]);
  return r.rowCount ? Number(r.rows[0].n) : 0;
}

export async function checkpointSeq(firmId, consumer = "router") {
  const r = await rootQuery("select last_seq from clara.relay_checkpoints where consumer = $1 and firm_id = $2", [
    consumer,
    firmId,
  ]);
  return r.rowCount ? Number(r.rows[0].last_seq) : null;
}

export async function countEventsByType(firmId, eventType) {
  const r = await rootQuery("select count(*) as c from clara.domain_events where firm_id = $1 and event_type = $2", [
    firmId,
    eventType,
  ]);
  return Number(r.rows[0].c);
}

/** All wake-bound event ids for a firm under the given active taxonomy decisions. */
export async function wakeBoundEventIds(firmId) {
  // Post-0007 the ONLY wake-bound type under the active taxonomy (v2) is the rig's
  // synthetic WAKE_EVENT_TYPE (background_review); the document family + everything
  // else route to context_update/ignore. Computed generically by joining the ACTIVE
  // taxonomy so the helper stays correct across a mid-test repoint (the flip test).
  const r = await rootQuery(
    `select e.id, e.seq
       from clara.domain_events e
       join clara.taxonomy_active a on true
       join clara.trigger_taxonomy t
         on t.version = a.version and t.event_type = e.event_type
      where e.firm_id = $1
        and t.decision in ('internal_task','notification','background_review')
      order by e.seq`,
    [firmId],
  );
  return r.rows.map((row) => ({ id: row.id, seq: Number(row.seq) }));
}

export async function wakeIntentsForFirm(firmId) {
  const r = await rootQuery(
    `select wi.event_id, wi.event_seq, wi.event_type, wi.decision, wi.taxonomy_version
       from clara.wake_intents wi
      where wi.firm_id = $1
      order by wi.event_seq`,
    [firmId],
  );
  return r.rows.map((row) => ({
    eventId: row.event_id,
    eventSeq: Number(row.event_seq),
    eventType: row.event_type,
    decision: row.decision,
    taxonomyVersion: Number(row.taxonomy_version),
  }));
}

export async function deadLettersForFirm(firmId, consumer = "router") {
  const r = await rootQuery(
    `select event_id, event_type, attempt_count, status, attempted_taxonomy_version
       from clara.relay_dead_letters where firm_id = $1 and consumer = $2 order by created_at`,
    [firmId, consumer],
  );
  return r.rows.map((row) => ({
    eventId: row.event_id,
    eventType: row.event_type,
    attemptCount: Number(row.attempt_count),
    status: row.status,
    attemptedVersion: row.attempted_taxonomy_version === null ? null : Number(row.attempted_taxonomy_version),
  }));
}

/** The currently active taxonomy version (superuser read). */
export async function activeTaxonomyVersion() {
  const r = await rootQuery("select version from clara.taxonomy_active limit 1");
  return r.rowCount ? Number(r.rows[0].version) : null;
}
